  "spr": { pl: "SPR", en: "stack-to-pot ratio", enAlt: [], def: "Efektywny stack podzielony przez pulę na początku ulicy (do planu rozdania liczy się go na flopie); mówi, jak głębokie są stacki w stosunku do puli (im niższy SPR, tym szybciej wszystko trafia do puli).", area: "strategy", forms: ["SPR"] },
  "mdf": { pl: "MDF", en: "minimum defense frequency", enAlt: [], def: "Najmniejsza część zakresu, którą trzeba bronić przed zakładem, żeby blef rywala ręką bez szans nie był automatycznie opłacalny.", area: "strategy", forms: ["MDF"] },
  "alpha": { pl: "alpha", en: "alpha", enAlt: [], def: "Jak często rywal musi spasować, żeby blef ręką bez szans wyszedł na zero; zależy od wielkości zakładu względem puli.", area: "strategy" },
  "variance": { pl: "wariancja", en: "variance", enAlt: [], def: "Rozrzut wyników wokół wartości oczekiwanej: nawet przy dobrej grze krótkie serie bywają mocno na minusie albo na plusie.", area: "mental", forms: ["wariancja","wariancji","wariancję","wariancją"] },
  "buy-in": { pl: "wpisowe", en: "buy-in", enAlt: [], def: "Kwota wejścia do turnieju albo do gry gotówkowej przy stole.", area: "mental", forms: ["wpisowe","wpisowego","wpisowym","wpisowych","wpisowymi"] },
  "bankroll": { pl: "bankroll", en: "bankroll", enAlt: [], def: "Cały zapas przeznaczony wyłącznie na grę w pokera; w tej aplikacji liczony we wpisowych (buy-in), nie w pieniądzach.", area: "mental" },
  "tilt": { pl: "tilt", en: "tilt", enAlt: [], def: "Stan, w którym emocje (złość, frustracja, euforia) pogarszają Twoje decyzje przy stole.", area: "mental" },
  "winrate": { pl: "winrate", en: "win rate", enAlt: [], def: "Średni wynik gracza na dłuższej próbie; w grach gotówkowych zwykle w bb/100, czyli dużych blindach na sto rozdań.", area: "mental" },
  "downswing": { pl: "downswing", en: "downswing", enAlt: [], def: "Okres wyraźnie gorszych wyników, zwykle większych strat, niż wynikałoby z umiejętności; przeciwieństwo upswingu.", area: "mental" },
  "session": { pl: "sesja", en: "session", enAlt: [], def: "Jedno posiedzenie przy pokerze, od rozpoczęcia do zakończenia gry.", area: "mental", forms: ["sesja","sesji","sesję","sesją","sesje","sesjach","sesjami"], skip: ["sesja ćwiczeń","sesji ćwiczeń","sesję ćwiczeń","sesją ćwiczeń","sesje ćwiczeń","sesjach ćwiczeń","sesjami ćwiczeń"] },
  "stakes": { pl: "stawka", en: "stakes", enAlt: [], def: "Wysokość blindów w grze gotówkowej albo wpisowego w turnieju; „mikrostawki” to najniższe poziomy.", area: "mental", forms: ["stawka","stawki","stawkę","stawką","stawce","stawek","stawkach","stawkami"], skip: ["obowiązkowe stawki"] },
  "standard-deviation": { pl: "odchylenie standardowe", en: "standard deviation", enAlt: [], def: "Miara rozrzutu wyników (pierwiastek z wariancji); w pokerze zwykle podawana w bb/100.", area: "mental", forms: ["odchylenie standardowe","odchylenia standardowego","odchyleniu standardowym","odchyleniem standardowym","odchylenie","odchylenia","odchyleniu","odchyleniem"] },
  "risk-of-ruin": { pl: "ryzyko bankructwa", en: "risk of ruin", enAlt: [], abbr: "RoR", def: "Prawdopodobieństwo, że kiedykolwiek stracisz cały bankroll, jeśli grasz dalej na tej samej stawce.", area: "mental", forms: ["ryzyko bankructwa","ryzyka bankructwa","ryzyku bankructwa","ryzykiem bankructwa"] },
