  "tournament": { pl: "turniej", en: "tournament", enAlt: [], def: "Forma gry, w której blindy rosną co pewien czas, a gra trwa, aż jeden gracz zbierze wszystkie żetony; nagrody dostają najwyżej sklasyfikowani.", area: "tournament", forms: ["turniej","turnieju","turnieje","turniejach","turniejem","turniejów","turniejami"] },
  "push-fold": { pl: "push/fold", en: "push/fold", enAlt: [], def: "Uproszczona strategia dla short stacków: przed flopem gra się albo all-in, albo pas.", area: "tournament" },
  "shove": { pl: "push", en: "shove", enAlt: ["jam","push"], def: "Zagranie all-in, zwykle jako przebicie przed flopem.", area: "tournament", forms: ["push","pusha","pushem","pushe","pushów","pushu","pushować","pushujesz","pushuje","pushują","pushuję","pushujący","pushującego","pushując","pushuj","pushowałbyś","pushował","pushowania","pushowanie"], skip: ["push/fold","push or fold","push-or-fold"] },
  "icm": { pl: "ICM", en: "Independent Chip Model", enAlt: [], def: "Model, który przelicza turniejowe żetony na wartość pieniężną z uwzględnieniem struktury wypłat i stacków wszystkich graczy.", area: "tournament", forms: ["ICM"] },
  "bubble": { pl: "bubble", en: "bubble", enAlt: [], def: "Faza turnieju tuż przed miejscami płatnymi, gdy do nagród brakuje odpadnięcia kilku graczy.", area: "tournament" },
  "bubble-factor": { pl: "bubble factor", en: "bubble factor", enAlt: [], def: "Wskaźnik z ICM: ile bardziej w turnieju boli przegrana niż cieszy wygrana tej samej liczby żetonów.", area: "tournament" },
  "cover": { pl: "pokrywać", en: "cover", enAlt: [], def: "Mieć co najmniej tyle żetonów co rywal. Gdy rywal Cię pokrywa, przegrany z nim all-in kończy Twój turniej.", area: "tournament", forms: ["pokrywać","pokrywasz","pokrywa","pokrywają","pokrywam","pokrywający","pokrywającego"], skip: ["pokrywa się","pokrywają się","pokrywać się","pokrywają straty"] },
  "risk-premium": { pl: "risk premium", en: "risk premium", enAlt: [], def: "Dodatkowe equity ponad to, czego wymagają pot odds, potrzebne w turnieju do ryzyka all-in, bo przegrana kosztuje więcej, niż daje wygrana.", area: "tournament" },
  "m-ratio": { pl: "M", en: "M-ratio", enAlt: [], def: "Stack podzielony przez sumę blindów i ante w jednym rozdaniu: na ile pełnych okrążeń (orbit) wystarczy żetonów bez gry.", area: "tournament" },
  "red-zone": { pl: "strefa czerwona", en: "red zone", enAlt: [], def: "Strefa bardzo niskiego M: zostaje głównie gra all-in albo pas.", area: "tournament", forms: ["strefa czerwona","strefie czerwonej","strefę czerwoną","strefy czerwonej","strefą czerwoną"] },
  "green-zone": { pl: "strefa zielona", en: "green zone", enAlt: [], def: "Strefa wysokiego M: stack pozwala grać swobodnie, zachowawczo albo agresywnie.", area: "tournament", forms: ["strefa zielona","strefie zielonej","strefę zieloną","strefy zielonej","strefą zieloną"] },
